package org.salahguard.app
import org.json.*
import org.junit.Assert.*
import org.junit.Test
import java.time.Instant
class PenaltyRulesTest {
 private val now="2026-11-03T10:00:00Z"
 private fun habit()=JSONObject().put("id","h").put("type","habit").put("start","2026-11-03").put("recovery",JSONObject().put("kind","charity").put("amountMinor",12550).put("currency","PKR"))
 @Test fun charityIsPrivateAndIdempotent(){val h=habit();val p=SecretRules.plan(listOf(h),emptyList(),"h","2026-11-03","slipped","2026-11-03","r","Asia/Karachi",now);assertTrue(p.publicRecords.isEmpty());val t=p.privateItems[1];assertFalse(t.has("routineId"));assertEquals("2026-11-04T10:00:00Z",t.getString("dueAt"));assertFalse(SecretRules.plan(listOf(h)+p.privateItems,emptyList(),"h","2026-11-03","slipped","2026-11-03","r","Asia/Karachi",now).changed)}
 @Test fun fractionalCharityMinorUnitsAreRejected(){val h=habit();h.getJSONObject("recovery").put("amountMinor",1.25);assertTrue(runCatching{SecretRules.plan(listOf(h),emptyList(),"h","2026-11-03","slipped","2026-11-03","r","Asia/Karachi",now)}.isFailure)}
 @Test fun givenCharityStaysDoneAcrossCorrections(){val h=habit();val first=SecretRules.plan(listOf(h),emptyList(),"h","2026-11-03","slipped","2026-11-03","r","Asia/Karachi",now);val task=first.privateItems[1].put("state","done").put("completedAt",now);val avoided=SecretRules.plan(listOf(h,first.privateItems[0],task),emptyList(),"h","2026-11-03","avoided","2026-11-03","r","Asia/Karachi",now);val items=(listOf(h,task)+avoided.privateItems).associateBy{it.getString("id")}.values.toList();val slipped=SecretRules.plan(items,emptyList(),"h","2026-11-03","slipped","2026-11-03","r","Asia/Karachi",now);val final=(items+slipped.privateItems).associateBy{it.getString("id")}.values.toList();assertEquals(0,PenaltyRules.schedules(final,emptyList()).length())}
 @Test fun exactlyFivePrivateTicks(){val t=JSONObject().put("id","t").put("type","recovery").put("state","pending").put("createdAt",now).put("dueAt","2026-11-04T10:00:00Z").put("amountMinor",100).put("name","Private");val schedule=PenaltyRules.schedules(listOf(t),emptyList()).getJSONObject(0);assertEquals(setOf("id","createdAt","dueAt"),schedule.keys().asSequence().toSet());assertEquals(listOf(4L,8L,12L,16L,20L),PenaltyRules.times(now,t.getString("dueAt")).map{(it-Instant.parse(now).toEpochMilli())/3600000});assertFalse(PenaltyRules.pending(schedule,emptyList(),Instant.parse(t.getString("dueAt")).toEpochMilli()));t.put("state","done");assertEquals(0,PenaltyRules.schedules(listOf(t),emptyList()).length())}
 @Test fun completedOrDeletedRoutineSuppresses(){val t=JSONObject().put("routineId","r").put("dueAt","2026-11-04T10:00:00Z");assertFalse(PenaltyRules.pending(t,emptyList(),0));val r=JSONObject().put("id","r").put("entity","routines");assertTrue(PenaltyRules.pending(t,listOf(r),0));val c=JSONObject().put("entity","routine_completions").put("data",JSONObject().put("routineId","r"));assertFalse(PenaltyRules.pending(t,listOf(r,c),0))}
}
